        mr = marker_rows[0]
        if max(r for r,c in pts) < mr:
            delta = mr - 1 - max(r for r,c in pts)
            dr = delta
        else:
            delta = min(r for r,c in pts) - mr - 1
            dr = -delta
        # shift object toward the horizontal marker; make a full-width line behind it
        for r,c in pts:
            out[r][c] = bg
        for r,c in pts:
