        line_r = top-1 if mr > bottom else bottom+1
        out[line_r] = [8]*w
    elif marker_cols:
        mc = marker_cols[0]
        if max(c for r,c in pts) < mc:
            dc = mc - 1 - max(c for r,c in pts)
